/**
 * engine-server/pipeline/orchestrator.ts — LLM 管道编排主入口
 *
 * 编排 L1-L5 五个阶段的顺序执行：
 *   L1_derive_roles   → Phase A
 *   L2_distill_genome  → Phase B
 *   L3_select_mode     → Phase C
 *   L4_match_skills    → Phase D
 *   L5_assemble_blueprint → Phase E
 *
 * 每个阶段：
 *   1. 调用 LLM (Gateway /v1/chat/completions)
 *   2. 解析 LLM 输出为结构化数据
 *   3. 生成 IncubationFrame 供前端轮询消费
 *   4. 更新 task-store 中的进度
 *
 * @packageDocumentation
 */
import type { GenerateBlueprintRequest, BlueprintDTO, DiagnosisReport, TaskDefinitionDTO } from '../types';
import type { PipelineSeeds } from './template-seeder';
/**
 * 执行完整 L1-L5 管道
 *
 * @param taskRequestId - 任务标识
 * @param request - 原始请求
 * @param abortSignal - 取消信号
 * @returns 组装好的 BlueprintDTO
 */
export declare function runPipeline(taskRequestId: string, request: GenerateBlueprintRequest, abortSignal: AbortSignal, seeds?: PipelineSeeds): Promise<BlueprintDTO>;
/** 增量更新操作类型 */
export type PartialPipelineAction = {
    type: 'add_role';
    name: string;
    responsibilities: string[];
    job?: string;
    celebrityId?: string;
} | {
    type: 'remove_role';
    roleId: string;
} | {
    type: 'split_role';
    roleId: string;
    splitInto: Array<{
        name: string;
        responsibilities: string[];
    }>;
} | {
    type: 'merge_roles';
    roleIds: string[];
    newName: string;
} | {
    type: 'change_layer';
    roleId: string;
    newLayer: string;
} | {
    type: 'recalculate_protocol';
};
/** 变更摘要 */
export interface ChangeSummary {
    action: string;
    details: string[];
    protocolWarning?: string;
}
/** runPipelinePartial 返回值 */
export interface PartialPipelineResult {
    blueprint: BlueprintDTO;
    changes: ChangeSummary;
    protocolWarning?: string;
}
/**
 * 执行增量管道操作。在现有 Blueprint 上执行增/删/改/协议重算。
 *
 * @param existingBlueprint - 当前团队蓝图
 * @param action - 增量操作
 * @param locale - 语言
 * @param abortSignal - 取消信号
 * @returns 更新后的蓝图 + 变更摘要
 */
export declare function runPipelinePartial(existingBlueprint: BlueprintDTO, action: PartialPipelineAction, locale: string, abortSignal: AbortSignal): Promise<PartialPipelineResult>;
/** 组织上下文（供总管家种子构建） */
export interface OrgContext {
    orgId: string;
    teams: Array<{
        name: string;
        blueprintId: string;
        roleCount: number;
    }>;
}
export declare function buildCoordinatorSeeds(orgCtx: OrgContext): {
    taskDefinition: TaskDefinitionDTO;
    seeds: PipelineSeeds;
    diagnosisReport: DiagnosisReport;
};
/**
 * 孵化总管家：完整走 L0→Pipeline→Blueprint→Template→安装。
 *
 * @param orgCtx 组织上下文
 * @param abortSignal 取消信号
 * @returns 总管家的 BlueprintDTO（含 deployableTemplate）
 */
export declare function incubateCoordinator(orgCtx: OrgContext, abortSignal: AbortSignal): Promise<BlueprintDTO>;
